data.code:
aws cognito-idp create-user-pool \
  --pool-name MyAppUserPool \
  --policies '{
    "PasswordPolicy": {
      "MinimumLength": 8,
      "RequireUppercase": true,
      "RequireLowercase": true,
      "RequireNumbers": true,
      "RequireSymbols": true
    }
  }' \
  --mfa-configuration 'OPTIONAL' \
  --schema '[{
    "Name": "email",
    "Required": true,
    "Mutable": true
  }, {
    "Name": "custom:role",
    "AttributeDataType": "String",
    "Mutable": true
  }]'
